        row=db.execute("SELECT count(*),coalesce(sum(bytes),0),coalesce(sum(status='VERIFIED'),0),coalesce(sum(CASE WHEN status='VERIFIED' THEN bytes ELSE 0 END),0) FROM files WHERE transfer=?",(item['id'],)).fetchone()
