                    data=storage.read(row['ident'],MAX_BYTES+1)
                    if len(data)!=row['bytes'] or hashlib.sha256(data).hexdigest()!=row['sha'] or not image_valid(data):raise StorageFailure('IMAGE_VERIFY_FAILED')
                done+=1
