    if epg_url:
        from epg_status import update as source_status
        source_status(portal_id, 'provider', 'RUNNING', running=True)
        info('[EPG] fetching XMLTV guide (URL redacted)')
        stage, raw = 'DOWNLOAD', None
        try:
